#pragma once

#include <cstdint>

namespace gba
{

// Sound effects generated by scripts/build_gba_audio.py.
enum class Sfx : uint8_t
{
    UI_CURSOR,     // cursor moved in a menu or list
    UI_CONFIRM,    // choice validated
    UI_CANCEL,     // back / cancel
    UI_OPEN,       // menu or overlay opened
    CARD_PLAY,
    HIT_SLASH,     // light attack
    HIT_HEAVY,     // big attack (10+ damage)
    HIT_BLUNT,     // attack fully or partly blocked
    BLOCK,         // block gained
    GOLD,
    RELIC,
    HEAL,
    DISCARD,
    ENEMY_DEATH,
    BUFF,
    DEBUFF,
    TURN_START,
    ERROR,         // invalid action (not enough energy or gold)
    TEXT_BLIP      // voice of a dialogue box typing its letters (#19)
};

// Plays a sound effect at the volume chosen in the options (silent when set to 0).
void play_sfx(Sfx sfx);

// Looping background themes generated by scripts/build_gba_audio.py.
enum class Music : uint8_t
{
    NONE,
    TITLE,
    MAP,
    COMBAT,
    ELITE,
    BOSS,
    VICTORY,
    GAME_OVER
};

// Requests a theme: the current one fades out, then the new one fades in. No-op if already playing.
void play_music(Music music);

// Advances music fades and applies the volume chosen in the options. Call once per frame.
void update_audio();

}
